import{_ as r,o,c as e,a3 as a}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.3 术语表（我自己也没法完全定义清楚，不看也罢）","description":"","frontmatter":{"translationSource":{"title":"1.3 术语表（我自己也没法完全定义清楚，不看也罢）","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=FBJt940VrXTDHkr5w3g0v3","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-3-glossary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-3-glossary"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-3-glossary"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-3-glossary"}]]},"headers":[],"relativePath":"zh/1-3-glossary.md","filePath":"zh/page-FBJt940VrXTDHkr5w3g0v3.md"}'),s={name:"zh/1-3-glossary.md"};function n(i,t,l,p,d,g){return o(),e("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-3-术语表-我自己也没法完全定义清楚-不看也罢" aria-hidden="true"></span><h1 id="_1-3-术语表-我自己也没法完全定义清楚-不看也罢" tabindex="-1">1.3 术语表（我自己也没法完全定义清楚，不看也罢） <a class="header-anchor" href="#_1-3-术语表-我自己也没法完全定义清楚-不看也罢" aria-label="Permalink to &quot;1\\.3 术语表（我自己也没法完全定义清楚，不看也罢）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>FBJt940VrXTDHkr5w3g0v3</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=FBJt940VrXTDHkr5w3g0v3" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><strong>智能切换</strong>：产线在不需要玩家手动干预的情形下发生生产方案的变化</p><p><strong>物料</strong>（暂且这么叫）：生产过程中的原材料或成品，包括各固体、液体、气体</p><p>**节点：**产线中或具体或抽象的一个位置，例如某机器的输入端或输出端，某条暗管的出口，某个传送带的一个端点。</p><p><strong>输入/输出节点</strong>：如果节点a在产线的边缘上，且所有通过节点a的物料都进入所指的部分产线，则称节点a为产线的输入节点；如果通过节点a的物料都是从这部分产线离开的，则称为输出节点。</p><p><strong>物流结构</strong>：传送带、管道、暗管、分汇流器等物流元件的连接组合，存在明确的一个或多个输入节点和输出节点。</p><p><strong>路径</strong>：物流结构中，只要存在任意一种阻塞或非阻塞情形，能使得物料能从输入节点a被运送至输出节点b，则称输入节点a和输出节点b之间存在路径。参考阻尼理论中的物流线概念。</p><p><strong>直接上游/下游</strong>：如果机器A的输出口连接一个物流结构的输入节点a，该物流结构的输出节点b连接机器B的输入口，且a和b存在路径，则机器A与该物流结构成为直接上下游关系，该物流结构与机器B成为直接上下游关系。</p><p><strong>上游</strong>：机器或物流结构的直接上游，及其直接上游的直接上游……都称为该机器或物流结构的上游</p><p><strong>下游</strong>：机器或物流结构的直接下游，及其直接下游的直接下游……都称为该机器或物流结构的下游</p><p><strong>生产结构</strong>：一个或多个机器、物流结构的连接组合，存在明确的一个或多个输入节点和输出节点。对于生产结构也可类似定义上游/下游。</p><p><strong>溢流</strong>：物流结构中，一个输入节点和多个输出节点存在路径，部分输出节点阻塞时，原先从这些输出节点输出的物料流向其他输出节点的现象。</p><p><strong>加压</strong>：连接生产结构的某原料取货口数*30/min大于生产结构消耗该原料的速度时即称该生产结构被加压，加压充分时连接取货口和生产结构的物流结构将保持阻塞。</p><p><strong>优先输出</strong>：游戏特性，当存储箱或多口暗管出口连接汇流器时，进入存储箱或多口暗管的物料会从阻尼较小的一端优先输出，详情见（<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>中的第二节优先输出）</p><p><strong>阻塞源</strong>：首先发生阻塞的节点，是所有阻塞的最下游。</p><p><a href="/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production">1.2 采用阻塞生产形式有什么好处</a></p><p><a href="/endfield-skydoc/zh/production-control-and-frontier-research">生产控制与前沿研究</a></p></div>',1)])])}const f=r(s,[["render",n]]);export{h as __pageData,f as default};
